import { useState, useEffect, useRef } from 'react';
import { useParams, Link } from 'react-router-dom';
import { QRCodeSVG } from 'qrcode.react';
import jsPDF from 'jspdf';
import html2canvas from 'html2canvas';
import {
  getApplicationByReference,
  getCertificateVerifyUrl,
  getCertificateExpiry,
  DEPARTMENT_NAMES,
} from '../../firebase/db';
import { useAuth } from '../../contexts/AuthContext';
import { useLanguage } from '../../i18n/LanguageContext';
import { assetPath } from '../../utils/assetPath';
import Layout from '../common/Layout';
import Card from '../common/Card';
import Button from '../common/Button';
import Alert from '../common/Alert';

const CertificateView = () => {
  const { reference } = useParams();
  const { profile } = useAuth();
  const { t } = useLanguage();
  const [application, setApplication] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [downloading, setDownloading] = useState(false);
  const certificateRef = useRef(null);

  useEffect(() => {
    const load = async () => {
      try {
        const app = await getApplicationByReference(reference);
        if (!app) {
          setError(t('certificate_not_found'));
        } else if (app.citizen_id !== profile?.uid) {
          setError('You are not authorized to view this certificate');
        } else if (app.status !== 'approved' && app.status !== 'completed') {
          setError('This certificate has not been approved yet');
        } else {
          setApplication(app);
        }
      } catch (err) {
        setError(err.message);
      } finally {
        setLoading(false);
      }
    };
    if (profile) load();
  }, [reference, profile, t]);

  const handleDownloadPDF = async () => {
    if (!certificateRef.current) return;

    setDownloading(true);
    try {
      // Capture the certificate as a high-resolution canvas
      const canvas = await html2canvas(certificateRef.current, {
        scale: 2,
        useCORS: true,
        backgroundColor: '#ffffff',
        logging: false,
      });

      const imgData = canvas.toDataURL('image/png');

      // Create an A4-sized PDF
      const pdf = new jsPDF({
        orientation: 'portrait',
        unit: 'mm',
        format: 'a4',
      });

      const pdfWidth = pdf.internal.pageSize.getWidth();
      const pdfHeight = pdf.internal.pageSize.getHeight();

      const imgWidth = pdfWidth - 20; // 10mm margins on each side
      const imgHeight = (canvas.height * imgWidth) / canvas.width;

      // If the image is taller than one page, scale to fit
      const finalHeight = imgHeight > pdfHeight - 20 ? pdfHeight - 20 : imgHeight;

      pdf.addImage(imgData, 'PNG', 10, 10, imgWidth, finalHeight);

      // Save with reference in filename
      pdf.save(`Certificate-${application.application_reference}.pdf`);
    } catch (err) {
      console.error('PDF generation failed:', err);
      alert('Failed to generate PDF. Please try again.');
    } finally {
      setDownloading(false);
    }
  };

  if (loading) {
    return (
      <Layout title={t('certificate')}>
        <Card><p>{t('loading')}</p></Card>
      </Layout>
    );
  }

  if (error) {
    return (
      <Layout title={t('certificate')}>
        <Alert type="error">{error}</Alert>
        <Link to="/dashboard">
          <Button>{t('back_to_dashboard')}</Button>
        </Link>
      </Layout>
    );
  }

  const verifyUrl = getCertificateVerifyUrl(application.application_reference);
  const expiry = getCertificateExpiry(application);
  const issueDate = application.completed_at?.toDate?.() || new Date();

  return (
    <Layout title={t('certificate')}>
      {/* Buttons — hidden when printing */}
      <div
        className="no-print"
        style={{ marginBottom: 15, display: 'flex', gap: 10, flexWrap: 'wrap' }}
      >
        <Button
          variant="success"
          onClick={handleDownloadPDF}
          disabled={downloading}
        >
          {downloading ? 'Generating PDF...' : `⬇ ${t('print_save_pdf')}`}
        </Button>
        <Link to="/dashboard">
          <Button variant="secondary">{t('back_to_dashboard')}</Button>
        </Link>
      </div>

      {/* Certificate — this is what gets converted to PDF */}
      <Card
        className="print-certificate"
        style={{ padding: 40, maxWidth: 800, margin: '0 auto' }}
      >
        <div
          ref={certificateRef}
          style={{
            border: '3px double #003366',
            padding: 30,
            background: 'white',
          }}
        >
          {/* Header */}
          <div style={{
            textAlign: 'center',
            borderBottom: '2px solid #003366',
            paddingBottom: 15,
            marginBottom: 25,
          }}>
            <img
              src={assetPath('/assets/logos/lesotho-coat-of-arms.png')}
              alt="Lesotho"
              style={{ height: 70, marginBottom: 10 }}
              crossOrigin="anonymous"
              onError={(e) => { e.target.style.display = 'none'; }}
            />
            <h1 style={{ margin: 0, color: '#003366', fontSize: 22 }}>
              {t('government_of_lesotho_full')}
            </h1>
            <p style={{ margin: '5px 0 0 0', color: '#666', fontSize: 14 }}>
              {DEPARTMENT_NAMES[application.department_id]}
            </p>
            <h2 style={{
              margin: '15px 0 0 0',
              color: '#003366',
              fontSize: 18,
              textTransform: 'uppercase',
              letterSpacing: 2,
            }}>
              {application.service_type}
            </h2>
          </div>

          {/* Body */}
          <div style={{ marginBottom: 30 }}>
            <p style={{ fontSize: 15, lineHeight: 1.7, color: '#333' }}>
              {t('this_certifies_that')}:
            </p>
            <p style={{
              fontSize: 20,
              fontWeight: 'bold',
              color: '#003366',
              textAlign: 'center',
              margin: '20px 0',
              padding: '15px 0',
              borderTop: '1px solid #ddd',
              borderBottom: '1px solid #ddd',
            }}>
              {application.citizen_name}
            </p>
            <p style={{ fontSize: 15, lineHeight: 1.7, color: '#333' }}>
              {t('national_id')}: <strong>{application.citizen_national_id}</strong>
            </p>
            <p style={{ fontSize: 15, lineHeight: 1.7, color: '#333' }}>
              {t('has_been_granted')}.
            </p>
          </div>

          {/* Details */}
          <div style={{
            display: 'grid',
            gridTemplateColumns: '1fr 1fr',
            gap: 20,
            marginBottom: 30,
            padding: 20,
            background: '#f9f9f9',
            borderRadius: 4,
          }}>
            <div>
              <div style={{ fontSize: 11, color: '#888', textTransform: 'uppercase', letterSpacing: 1 }}>
                {t('reference_number')}
              </div>
              <div style={{ fontSize: 15, fontWeight: 'bold', color: '#003366', marginTop: 3 }}>
                {application.application_reference}
              </div>
            </div>
            <div>
              <div style={{ fontSize: 11, color: '#888', textTransform: 'uppercase', letterSpacing: 1 }}>
                {t('issue_date')}
              </div>
              <div style={{ fontSize: 15, fontWeight: 'bold', color: '#003366', marginTop: 3 }}>
                {issueDate.toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric' })}
              </div>
            </div>
            {expiry && (
              <div>
                <div style={{ fontSize: 11, color: '#888', textTransform: 'uppercase', letterSpacing: 1 }}>
                  {t('valid_until')}
                </div>
                <div style={{ fontSize: 15, fontWeight: 'bold', color: '#003366', marginTop: 3 }}>
                  {expiry.toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric' })}
                </div>
              </div>
            )}
            <div>
              <div style={{ fontSize: 11, color: '#888', textTransform: 'uppercase', letterSpacing: 1 }}>
                {t('status')}
              </div>
              <div style={{ fontSize: 15, fontWeight: 'bold', color: '#006600', marginTop: 3 }}>
                {t('approved').toUpperCase()}
              </div>
            </div>
          </div>

          {/* QR Code */}
          <div style={{
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'flex-end',
            gap: 20,
            borderTop: '1px solid #ddd',
            paddingTop: 20,
          }}>
            <div style={{ flex: 1 }}>
              <p style={{ fontSize: 12, color: '#666', margin: 0 }}>
                {t('scan_qr')}
              </p>
              <p style={{ fontSize: 11, color: '#888', margin: '5px 0 0 0', wordBreak: 'break-all' }}>
                {verifyUrl}
              </p>
            </div>
            <div style={{ background: 'white', padding: 10, border: '1px solid #ddd', borderRadius: 4 }}>
              <QRCodeSVG
                value={verifyUrl}
                size={120}
                level="M"
                bgColor="#ffffff"
                fgColor="#003366"
              />
            </div>
          </div>

          {/* Footer */}
          <div style={{ textAlign: 'center', marginTop: 30, fontSize: 11, color: '#888' }}>
            <p style={{ margin: 0 }}>
              This certificate is electronically generated. Any alteration renders it invalid.
            </p>
            <p style={{ margin: '5px 0 0 0' }}>
              © 2026 {t('government_of_lesotho_full')}
            </p>
          </div>
        </div>
      </Card>
    </Layout>
  );
};

export default CertificateView;